#This Test Generated by ChatGPT

import torch
import torch.nn as nn

from lexicore.tokenization.bpe_tokenizer import BPETokenizer, BPEVocabulary
from lexicore.word2vec.context import ContextTargetGenerator
from lexicore.word2vec.negative_sampling import NegativeSampling
from lexicore.word2vec.skipgram import SkipGramNN


def test_word2vec_full_pipeline():

    corpus = """
    the company stores customer records
    employees access internal documents
    the system validates user credentials
    administrators manage permissions
    """

    tokenizer = BPETokenizer(
        vocab_size=100
    )

    tokenizer.fit(corpus)

    tokens = tokenizer.tokenize(corpus)

    assert len(tokens) > 0

    vocabulary = BPEVocabulary(
        tokens
    )

    assert len(vocabulary) > 0

    token_ids = vocabulary.encode(
        tokens
    )

    assert len(token_ids) == len(tokens)

    context_generator = ContextTargetGenerator(
        context_window=2
    )

    pairs = context_generator.generate(
        token_ids
    )

    assert len(pairs) > 0

    target_ids = torch.tensor(
        [pair[0] for pair in pairs],
        dtype=torch.long
    )

    context_ids = torch.tensor(
        [pair[1] for pair in pairs],
        dtype=torch.long
    )

    assert target_ids.shape == context_ids.shape

    negative_sampler = NegativeSampling(
        word_freq=vocabulary.word_freq,
        word2idx=vocabulary.word2idx,
        negative_sampler=2
    )

    negative_ids = []

    for target_id, context_id in zip(
        target_ids,
        context_ids
    ):

        negatives = negative_sampler.sample(
            target_id.item(),
            context_id.item()
        )

        negative_ids.append(
            negatives
        )

    negative_ids = torch.tensor(
        negative_ids,
        dtype=torch.long
    )

    assert negative_ids.shape == (
        len(pairs),
        2
    )

    model = SkipGramNN(
        vocab_size=len(vocabulary),
        embedding_dim=16
    )

    positive_scores, negative_scores = model(
        target_ids,
        context_ids,
        negative_ids
    )

    assert positive_scores.shape == (
        len(pairs),
    )

    assert negative_scores.shape == (
        len(pairs),
        2
    )

    positive_labels = torch.ones_like(
        positive_scores
    )

    negative_labels = torch.zeros_like(
        negative_scores
    )

    criterion = nn.BCEWithLogitsLoss()

    positive_loss = criterion(
        positive_scores,
        positive_labels
    )

    negative_loss = criterion(
        negative_scores,
        negative_labels
    )

    loss = positive_loss + negative_loss

    assert torch.isfinite(loss)

    loss.backward()

    assert model.input_embeddings.weight.grad is not None

    assert model.output_embeddings.weight.grad is not None

    assert model.input_embeddings.weight.grad.shape == (
        len(vocabulary),
        16
    )

    assert model.output_embeddings.weight.grad.shape == (
        len(vocabulary),
        16
    )